import pyotp
import pytest

from app.auth import AuthError, get_session, login, otp_header
from app.config import USERS


def otp_for(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", otp_for("alice"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", otp_for("alice"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", otp_for("alice"))


def test_login_con_otp_invalido_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_acepta_cualquier_codigo_si_se_sustituye_verificar_otp(monkeypatch):
    monkeypatch.setattr("app.auth.verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "codigo-cualquiera")
    assert s.username == "alice"


def test_otp_header_lee_cabecera_x_otp(client):
    @client.app.get("/_test_otp_header")
    def _endpoint(otp: str = otp_header):
        return {"otp": otp}

    assert client.get("/_test_otp_header", headers={"X-OTP": "123456"}).json() == {"otp": "123456"}
    assert client.get("/_test_otp_header").json() == {"otp": ""}


def test_endpoint_login(client):
    body = {"username": "bob", "password": "bob-pass", "otp": otp_for("bob")}
    assert client.post("/login", json=body).status_code == 200
    assert client.post("/login", json={**body, "password": "x"}).status_code == 401
    assert client.post("/login", json={**body, "otp": "000000"}).status_code == 401
    assert client.post("/login", json={"username": "bob", "password": "bob-pass"}).status_code == 401

